// ===== SETTINGS - edit these values =====
return [{ json: {
  INSTANCE_NAME: 'my n8n',
  N8N_URL: 'http://localhost:5678',   // this n8n instance, as n8n itself reaches it
  VERSION_OVERRIDE: '',               // leave empty: auto-detected. Set e.g. '2.42.1' only if you run a beta/next build
  WEEKLY_REPORT_DAY: '1',             // 0=Sun ... 6=Sat: full report even when nothing is new. '' = off
  ALWAYS_SEND: false                  // true = email every run (useful while testing)
} }];

// n8n SENTINEL - core logic (pure function; the same code goes into the workflow's Code node).
// Inputs: n8n security audit report, n8n stable versions list, GitHub security advisories for n8n-io/n8n,
// optional VERSION_OVERRIDE, and the previous run (for "new since last time").
// Branch-aware: a fix backported to your own version line (same major.minor) counts as patched.
// (c) 2026 Spiridon Tsakonas (Cyrus Nash) - Light in the Dark Solutions - All Rights Reserved

const parseV = s => { const m = String(s || '').trim().match(/^v?(\d+)\.(\d+)\.(\d+)/); return m ? [+m[1], +m[2], +m[3]] : null; };
const cmp = (a, b) => (a[0] - b[0]) || (a[1] - b[1]) || (a[2] - b[2]);
// "< 2.42.1", ">= 2.0.0, < 2.41.4", "<= 1.2.3", "= 1.0.0"
function inRange(v, range) {
  if (!range) return false;
  return range.split(',').map(x => x.trim()).filter(Boolean).every(cond => {
    const m = cond.match(/^(<=|>=|<|>|=)?\s*v?(\d+\.\d+\.\d+)/); if (!m) return false;
    const c = cmp(v, parseV(m[2])), op = m[1] || '=';
    return op === '<' ? c < 0 : op === '<=' ? c <= 0 : op === '>' ? c > 0 : op === '>=' ? c >= 0 : c === 0;
  });
}
function patchedOnMyLine(v, patchedList) {
  return patchedList.some(p => { const pv = parseV(String(p).replace(/^[^\d]*/, '')); return pv && pv[0] === v[0] && pv[1] === v[1] && cmp(v, pv) >= 0; });
}
function isAffected(version, advisory) {
  const v = parseV(version); if (!v) return { affected: null, reason: 'unknown version' };
  const vulns = (advisory.vulnerabilities || []).filter(x => !x.package || x.package.name === 'n8n');
  const hit = vulns.filter(x => inRange(v, x.vulnerable_version_range));
  if (!hit.length) return { affected: false, reason: 'version outside every affected range' };
  const patched = vulns.map(x => x.patched_versions).filter(Boolean).flatMap(p => p.split(','));
  if (patchedOnMyLine(v, patched)) return { affected: false, reason: 'fix backported to your ' + v[0] + '.' + v[1] + '.x line' };
  const fixes = patched.map(p => p.trim()).filter(Boolean);
  return { affected: true, reason: 'in range ' + hit.map(x => x.vulnerable_version_range).join(' | '), fixes };
}
function detectVersion({ audit, versions, override }) {
  if (parseV(override)) return { version: parseV(override).join('.'), source: 'VERSION_OVERRIDE' };
  const inst = (audit && audit['Instance Risk Report'] && audit['Instance Risk Report'].sections) || [];
  for (const s of inst) { const m = String(s.description || '').match(/Currently at version (\d+\.\d+\.\d+)/); if (m) return { version: m[1], source: 'security audit (instance is outdated)' }; }
  const names = (versions || []).map(x => x.name).filter(parseV).sort((a, b) => cmp(parseV(b), parseV(a)));
  if (names.length) return { version: names[0], source: 'n8n stable release list (audit reports no missing updates)' };
  return { version: null, source: 'unknown - set VERSION_OVERRIDE' };
}
const SEV_POINTS = { critical: 40, high: 25, medium: 10, low: 3 };
function analyze({ audit, versions, advisories, override, previous }) {
  const ver = detectVersion({ audit, versions, override });
  const open = [];
  for (const a of advisories || []) {
    if (a.state && a.state !== 'published') continue;
    const r = isAffected(ver.version, a);
    if (r.affected) open.push({ id: a.ghsa_id, severity: a.severity || 'unknown', summary: a.summary, url: a.html_url, published: (a.published_at || '').slice(0, 10), fixes: r.fixes });
  }
  const findings = [];
  for (const [report, body] of Object.entries(audit || {})) {
    for (const s of (body && body.sections) || []) {
      if (s.title === 'Security settings') continue;
      const n = Array.isArray(s.location) ? s.location.length : (s.nextVersions ? s.nextVersions.length : 1);
      findings.push({ id: report + ' / ' + s.title, report, title: s.title, count: n, recommendation: s.recommendation || '',
        where: (s.location || []).slice(0, 5).map(l => l.workflowName ? `${l.workflowName} -> ${l.nodeName || l.name || ''}` : (l.name || l.kind || '')).filter(Boolean) });
    }
  }
  // BROKEN BY POLICY: workflows that use a node this instance has disabled (nodesExclude / nodesInclude) - they cannot run.
  const sec = (((audit || {})['Instance Risk Report'] || {}).sections || []).find(s => s.settings && s.settings.nodes);
  if (sec) {
    const list = v => String(v || '').split(',').map(x => x.trim()).filter(x => x && x !== 'none');
    const excl = new Set(list(sec.settings.nodes.nodesExclude)), incl = new Set(list(sec.settings.nodes.nodesInclude));
    const blocked = t => excl.has(t) || (incl.size > 0 && !incl.has(t));
    const locs = (((audit || {})['Nodes Risk Report'] || {}).sections || []).flatMap(s => s.location || []);
    const seen = new Set(), hits = [];
    for (const l of locs) { const k = l.workflowId + '/' + l.nodeId; if (l.nodeType && blocked(l.nodeType) && !seen.has(k)) { seen.add(k); hits.push(l); } }
    if (hits.length) {
      const wf = [...new Set(hits.map(h => h.workflowId))];
      findings.push({ id: 'Policy / Workflows using disabled nodes', report: 'Policy', title: 'Workflows using disabled nodes', count: wf.length,
        recommendation: 'These workflows cannot run on this instance. Replace the disabled node, or remove it from NODES_EXCLUDE if you accept the risk.',
        where: wf.slice(0, 10).map(id => { const hs = hits.filter(h => h.workflowId === id); return `"${hs[0].workflowName}" [id ${id}]: ${hs.map(h => h.nodeName).join(', ')} (${[...new Set(hs.map(h => h.nodeType.replace('n8n-nodes-base.', '')))].join(', ')})`; }) });
    }
  }
  let score = 0;
  for (const o of open) score += SEV_POINTS[o.severity] || 5;
  for (const f of findings) {
    if (/outdated/i.test(f.title)) score += 15;
    else if (/disabled nodes/i.test(f.title)) score += Math.min(30, 10 * f.count);
    else if (/webhook/i.test(f.title)) score += Math.min(20, 5 * f.count);
    else if (/credential/i.test(f.title)) score += Math.min(10, 2 * f.count);
    else if (/risky nodes|community/i.test(f.title)) score += Math.min(10, Math.ceil(f.count / 5));
    else score += Math.min(10, f.count);
  }
  score = Math.min(100, score);
  const grade = score === 0 ? 'A' : score <= 10 ? 'B' : score <= 25 ? 'C' : score <= 50 ? 'D' : 'F';
  const prevIds = new Set((previous && previous.openIds) || []), prevF = new Set((previous && previous.findingIds) || []);
  const newAdvisories = open.filter(o => !prevIds.has(o.id));
  const newFindings = findings.filter(f => !prevF.has(f.id));
  const urgent = newAdvisories.filter(o => ['critical', 'high'].includes(o.severity));
  // the plan: deterministic, ordered by danger - no AI guessing in security advice
  const plan = [];
  if (open.length) {
    const fixes = [...new Set(open.flatMap(o => o.fixes || []))];
    plan.push(`Upgrade n8n: ${open.length} published advisory(ies) affect version ${ver.version}. Fixed in: ${fixes.join(' or ')}.`);
  }
  for (const f of findings.filter(x => /disabled nodes/i.test(x.title))) plan.push(`Fix ${f.count} workflow(s) that cannot run - they use nodes disabled on this instance: ${f.where.join('; ')}`);
  for (const f of findings.filter(x => /webhook/i.test(x.title))) plan.push(`Protect ${f.count} webhook(s) without authentication: ${f.where.join('; ')}`);
  for (const f of findings.filter(x => /outdated/i.test(x.title))) plan.push('Update this instance: the audit reports missing updates.');
  for (const f of findings.filter(x => /credential/i.test(x.title))) plan.push(`Review ${f.count} credential(s) not used by any active workflow - delete what you no longer need.`);
  for (const f of findings.filter(x => /risky nodes|community/i.test(x.title))) plan.push(`Review ${f.count} use(s) of nodes that can run code on the server (${f.title}).`);
  return { checked_at: new Date().toISOString(), version: ver.version, version_source: ver.source, score, grade,
    open_advisories: open, findings, new_advisories: newAdvisories, new_findings: newFindings,
    alert: urgent.length > 0 || newFindings.some(f => /webhook|outdated|disabled nodes/i.test(f.title)), plan,
    memory: { openIds: open.map(o => o.id), findingIds: findings.map(f => f.id) } };
}

// ---------------- n8n glue ----------------
const cfg = $('Set Sentinel Settings').first().json;
const auditRaw = $('Run n8n Security Audit').first().json || {};
const auditOk = !auditRaw.error && (Object.keys(auditRaw).length === 0 || Object.keys(auditRaw).some(k => /Risk Report$/.test(k)));
const audit = auditOk ? auditRaw : {};
const versions = $('Fetch Stable n8n Versions').all().map(i => i.json).filter(v => v && v.name);
const advItems = $('Fetch GitHub Security Advisories').all().map(i => i.json);
const advisoriesOk = advItems.length > 0 && advItems.every(a => a && a.ghsa_id);
const store = $getWorkflowStaticData('global');
const r = analyze({ audit, versions, advisories: advisoriesOk ? advItems : [], override: cfg.VERSION_OVERRIDE, previous: store.last });
const problems = [];
if (!auditOk) problems.push('The n8n security audit FAILED (' + String(auditRaw.error && (auditRaw.error.message || auditRaw.error) || 'unexpected answer').slice(0, 200) + '). Check N8N_URL and the API key credential.');
if (!advisoriesOk) problems.push('Security advisories could not be fetched from GitHub - advisory check SKIPPED this run (not "0 advisories").');
if (!r.version) problems.push('Instance version unknown - set VERSION_OVERRIDE in Set Sentinel Settings. Advisory matching was not possible.');
store.last = r.memory;
store.history = (store.history || []).concat([{ date: r.checked_at.slice(0, 10), score: r.score, grade: r.grade }]).slice(-30);
const trend = store.history.map(h => `${h.date} ${h.grade} (${h.score})`).join(' | ');
const weekly = cfg.WEEKLY_REPORT_DAY !== '' && new Date().getDay() === Number(cfg.WEEKLY_REPORT_DAY);
const send = problems.length > 0 || r.alert || weekly || cfg.ALWAYS_SEND === true;
const newCount = r.new_advisories.length + r.new_findings.length;
const L = [];
L.push(`n8n SENTINEL - security report for ${cfg.INSTANCE_NAME}`);
L.push(`Checked: ${r.checked_at}`);
L.push(`Version: ${r.version || 'unknown'} (from ${r.version_source})`);
L.push(`Risk score: ${r.score}/100 - grade ${r.grade}   (0 = clean, A best, F worst)`);
if (problems.length) { L.push('', '!! CHECK PROBLEMS'); problems.forEach(p => L.push(' - ' + p)); }
L.push('', `NEW SINCE LAST RUN: ${newCount}`);
r.new_advisories.forEach(o => L.push(` - [${o.severity.toUpperCase()}] ${o.summary} (${o.id}) ${o.url}`));
r.new_findings.forEach(f => L.push(` - ${f.title} (${f.count})`));
L.push('', `OPEN ADVISORIES AFFECTING YOUR VERSION: ${r.open_advisories.length}`);
r.open_advisories.slice(0, 25).forEach(o => L.push(` - [${o.severity.toUpperCase()}] ${o.summary} - fixed in ${(o.fixes || []).join(' or ')} - ${o.url}`));
L.push('', 'AUDIT FINDINGS:');
r.findings.forEach(f => { L.push(` - ${f.title} (${f.count})`); f.where.slice(0, 5).forEach(w => L.push(`     ${w}`)); });
L.push('', 'FIX PLAN (most dangerous first):');
(r.plan.length ? r.plan : ['Nothing to fix today.']).forEach((p, i) => L.push(` ${i + 1}. ${p}`));
L.push('', 'TREND: ' + trend);
L.push('', 'Version matching is branch-aware: a fix backported to your own version line counts as patched.');
return [{ json: { ...r, problems, send, weekly, trend,
  subject: `n8n Sentinel: grade ${r.grade} (${r.score}/100)` + (problems.length ? ' - CHECK PROBLEM' : newCount ? ` - ${newCount} new` : weekly ? ' - weekly report' : ''),
  report_text: L.join('\n') } }];
